import { phpDigitsToVersion } from './cwpConf';

// ─────────────────────────────────────────────────────────────────────────────
// nginx vhost files generated by CWP (/etc/nginx/conf.d/vhosts/<fqdn>[.ssl].conf,
// docs/cwp/vhost-nginx-sample.anon.conf). A small block tokenizer (comments,
// quotes, braces) → directive tree → per `server` facts: listen (ssl),
// server_name list, the first `root` anywhere inside the server (CWP puts it
// in a nested static location), the proxy_pass of `location /`, websocket
// headers, fastcgi_pass to /opt/alt/php-fpmXX, redirects, certificates.
// `include` is ignored (proxy.inc carries nothing we need).
// ─────────────────────────────────────────────────────────────────────────────

export interface NginxDirective {
  name: string;
  args: string[];
  block: NginxDirective[] | null;
}

type Tok = { t: 'word'; v: string } | { t: '{' } | { t: '}' } | { t: ';' };

function tokenize(text: string): Tok[] {
  const toks: Tok[] = [];
  let i = 0;
  const n = text.length;
  while (i < n) {
    const c = text[i];
    if (c === '#') {
      while (i < n && text[i] !== '\n') i += 1;
      continue;
    }
    if (c === ' ' || c === '\t' || c === '\n' || c === '\r') { i += 1; continue; }
    if (c === '{' || c === '}' || c === ';') { toks.push({ t: c }); i += 1; continue; }
    if (c === '"' || c === "'") {
      const q = c;
      let v = '';
      i += 1;
      while (i < n && text[i] !== q) {
        if (text[i] === '\\' && i + 1 < n) { v += text[i + 1]; i += 2; continue; }
        v += text[i];
        i += 1;
      }
      i += 1;
      toks.push({ t: 'word', v });
      continue;
    }
    let v = '';
    while (i < n) {
      const d = text[i];
      if (d === ' ' || d === '\t' || d === '\n' || d === '\r' || d === ';' || d === '{' || d === '}') break;
      if (d === '\\' && i + 1 < n) { v += d + text[i + 1]; i += 2; continue; }
      // ${var} inside a word is part of the word.
      if (d === '$' && text[i + 1] === '{') {
        const end = text.indexOf('}', i);
        if (end > 0) { v += text.slice(i, end + 1); i = end + 1; continue; }
      }
      v += d;
      i += 1;
    }
    toks.push({ t: 'word', v });
  }
  return toks;
}

/** Parses an nginx configuration into a directive tree (never throws; unbalanced braces are closed at EOF). */
export function parseNginxConfig(text: string): NginxDirective[] {
  const toks = tokenize(text);
  let pos = 0;
  const parseBlock = (depth: number): NginxDirective[] => {
    const out: NginxDirective[] = [];
    let words: string[] = [];
    while (pos < toks.length) {
      const tk = toks[pos];
      pos += 1;
      if (tk.t === 'word') { words.push(tk.v); continue; }
      if (tk.t === ';') {
        if (words.length > 0) out.push({ name: words[0], args: words.slice(1), block: null });
        words = [];
        continue;
      }
      if (tk.t === '{') {
        const block = depth > 64 ? [] : parseBlock(depth + 1);
        out.push({ name: words[0] ?? '', args: words.slice(1), block });
        words = [];
        continue;
      }
      // '}'
      if (depth > 0) return out;
    }
    return out;
  };
  return parseBlock(0);
}

export interface NginxListen {
  address: string | null;
  port: number | null;
  ssl: boolean;
}

export interface UrlTarget {
  scheme: 'http' | 'https';
  host: string;
  port: number;
  path: string;
}

export interface NginxRedirect {
  code: number;
  target: string;
  /** Host of the target when it is an absolute URL with a literal host (null for $host…). */
  host: string | null;
}

export interface NginxServer {
  serverNames: string[];
  listens: NginxListen[];
  ssl: boolean;
  root: string | null;
  /** proxy_pass of `location /` (direct directive of that location). */
  proxyPass: UrlTarget | null;
  /** Raw proxy_pass value of location / (upstream names, variables…). */
  proxyPassRaw: string | null;
  websocket: boolean;
  /** /opt/alt/php-fpmXX socket in a fastcgi_pass ('8.1'…). */
  fpmVersion: string | null;
  fastcgi: boolean;
  redirect: NginxRedirect | null;
  sslCertificate: string | null;
}

/** http(s)://host[:port][/path] → target ('http://[::1]:8080' supported); null for unix: / variables / upstream names. */
export function parseUrlTarget(raw: string, upstreams?: Map<string, string>): UrlTarget | null {
  const m = /^(https?):\/\/(\[[0-9a-fA-F:.]+\]|[^/:$\s]+)(?::(\d{1,5}))?(\/.*)?$/.exec(raw.trim());
  if (!m) return null;
  const scheme = m[1] as 'http' | 'https';
  let host = m[2].replace(/^\[(.*)\]$/, '$1');
  let port = m[3] ? Number(m[3]) : scheme === 'https' ? 443 : 80;
  if (!m[3] && upstreams?.has(host)) {
    const up = /^(\[[0-9a-fA-F:.]+\]|[^:\s]+)(?::(\d{1,5}))?$/.exec(upstreams.get(host) as string);
    if (up) {
      host = up[1].replace(/^\[(.*)\]$/, '$1');
      port = up[2] ? Number(up[2]) : 80;
    }
  }
  if (port < 1 || port > 65535) return null;
  return { scheme, host: host.toLowerCase(), port, path: m[4] ?? '' };
}

function walk(ds: NginxDirective[], fn: (d: NginxDirective, parents: NginxDirective[]) => void, parents: NginxDirective[] = []): void {
  for (const d of ds) {
    fn(d, parents);
    if (d.block) walk(d.block, fn, [...parents, d]);
  }
}

function parseListen(args: string[]): NginxListen {
  const first = args[0] ?? '';
  let address: string | null = null;
  let port: number | null = null;
  const v6 = /^\[([^\]]+)\](?::(\d+))?$/.exec(first);
  if (v6) { address = v6[1]; port = v6[2] ? Number(v6[2]) : 80; }
  else if (/^\d+$/.test(first)) port = Number(first);
  else {
    const i = first.lastIndexOf(':');
    if (i > 0) { address = first.slice(0, i); port = Number(first.slice(i + 1)) || null; }
    else { address = first || null; port = 80; }
  }
  return { address, port, ssl: args.slice(1).includes('ssl') };
}

function redirectOf(d: NginxDirective): NginxRedirect | null {
  if (d.name === 'return' && d.args.length >= 2 && /^30[1278]$/.test(d.args[0])) {
    const target = d.args[1];
    const h = /^https?:\/\/([^/:$\s]+)/.exec(target);
    return { code: Number(d.args[0]), target, host: h ? h[1].toLowerCase() : null };
  }
  if (d.name === 'rewrite' && d.args.length >= 3 && /^(permanent|redirect)$/.test(d.args[2]) && /^\^?\/?\(?\.\*\)?\$?$|^\^$/.test(d.args[0])) {
    const target = d.args[1];
    const h = /^https?:\/\/([^/:$\s]+)/.exec(target);
    return { code: d.args[2] === 'permanent' ? 301 : 302, target, host: h ? h[1].toLowerCase() : null };
  }
  return null;
}

const FPM_SOCKET = /unix:\/opt\/alt\/php-fpm(\d{2,3})\//;

function serverFacts(server: NginxDirective, upstreams: Map<string, string>): NginxServer {
  const body = server.block ?? [];
  const names: string[] = [];
  const listens: NginxListen[] = [];
  let root: string | null = null;
  let proxyPassRaw: string | null = null;
  let websocket = false;
  let fpmVersion: string | null = null;
  let fastcgi = false;
  let redirect: NginxRedirect | null = null;
  let sslCertificate: string | null = null;
  let sslOn = false;

  for (const d of body) {
    if (d.name === 'server_name') names.push(...d.args.map((a) => a.toLowerCase().replace(/\.$/, '')).filter((a) => a !== '' && a !== '_'));
    else if (d.name === 'listen') listens.push(parseListen(d.args));
    else if (d.name === 'ssl_certificate' && d.args[0]) sslCertificate = d.args[0];
    else if (d.name === 'ssl' && d.args[0] === 'on') sslOn = true;
    else if (!redirect) redirect = redirectOf(d);
  }

  walk(body, (d, parents) => {
    if (d.name === 'root' && root === null && d.args[0]) root = d.args[0].replace(/\/+$/, '') || '/';
    if (d.name === 'fastcgi_pass' && d.args[0]) {
      fastcgi = true;
      const m = FPM_SOCKET.exec(d.args[0]);
      if (m && !fpmVersion) fpmVersion = phpDigitsToVersion(m[1]);
    }
    if (d.name === 'proxy_set_header' && d.args.length >= 2) {
      const h = d.args[0].toLowerCase();
      const v = d.args.slice(1).join(' ').toLowerCase();
      if (h === 'upgrade' || (h === 'connection' && v.includes('upgrade'))) websocket = true;
    }
    if (d.name === 'proxy_http_version' && parents.length === 0) { /* not enough alone for websocket */ }
  });

  // location / (exact prefix, no modifier, or '=' /): its own proxy_pass / return.
  for (const d of body) {
    if (d.name !== 'location' || !d.block) continue;
    const path = d.args.length === 1 ? d.args[0] : d.args[0] === '=' || d.args[0] === '^~' ? d.args[1] : null;
    if (path !== '/') continue;
    for (const inner of d.block) {
      if (inner.name === 'proxy_pass' && inner.args[0] && proxyPassRaw === null) proxyPassRaw = inner.args[0];
      if (!redirect) redirect = redirectOf(inner);
    }
  }

  return {
    serverNames: names,
    listens,
    ssl: sslOn || listens.some((l) => l.ssl || l.port === 443),
    root,
    proxyPass: proxyPassRaw ? parseUrlTarget(proxyPassRaw, upstreams) : null,
    proxyPassRaw,
    websocket,
    fpmVersion,
    fastcgi,
    redirect,
    sslCertificate,
  };
}

/** Every `server` block of a vhost file (top level or inside `http`). */
export function parseNginxVhost(text: string): NginxServer[] {
  const tree = parseNginxConfig(text);
  const upstreams = new Map<string, string>();
  walk(tree, (d) => {
    if (d.name === 'upstream' && d.args[0] && d.block) {
      const s = d.block.find((x) => x.name === 'server' && x.args[0]);
      if (s) upstreams.set(d.args[0].toLowerCase(), s.args[0]);
    }
  });
  const servers: NginxServer[] = [];
  walk(tree, (d, parents) => {
    if (d.name === 'server' && d.block && !parents.some((p) => p.name === 'server' || p.name === 'upstream')) {
      servers.push(serverFacts(d, upstreams));
    }
  });
  return servers;
}

const CWP_SERVICE_PREFIXES = ['webmail.', 'mail.', 'cpanel.'];

/** The webmail. / mail. / cpanel. sub-servers CWP adds to every vhost (they proxy to cwpsrv): not sites. */
export function isCwpServiceServer(server: { serverNames: string[] }, fqdn: string): boolean {
  if (server.serverNames.length === 0) return false;
  return server.serverNames.every((n) => CWP_SERVICE_PREFIXES.some((p) => n === `${p}${fqdn}`));
}
